INSERT IGNORE INTO products (slug,name,category,occasion,price,old_price,image,description,flowers,badge) VALUES ('nang-tho','Nàng thơ','Bó hoa','Tình yêu',550000,650000,'/images/rose.jpg','Hồng pastel dịu dàng, gói trong những lớp giấy màu kem. Một lời thương nhẹ nhàng dành cho người bạn luôn nghĩ đến.','Hồng pastel, cẩm chướng, lá bạc','Được yêu thích');
