INSERT IGNORE INTO products (slug,name,category,occasion,price,old_price,image,description,flowers,badge) VALUES ('cham-vao-ha','Chạm vào hạ','Bó hoa','Chúc mừng',480000,NULL,'/images/sunshine.jpg','Sắc hoa rực rỡ như một ngày đầy nắng. Dành tặng những khởi đầu mới và niềm vui vừa chớm.','Hoa theo mùa, cúc, lá phụ',NULL);
INSERT IGNORE INTO products (slug,name,category,occasion,price,old_price,image,description,flowers,badge) VALUES ('hong-may','Hồng mây','Giỏ hoa','Sinh nhật',750000,850000,'/images/pink.jpg','Những sắc hồng đan xen, vừa ngọt ngào vừa tự nhiên. Giỏ hoa được cắm tay để từng bông có khoảng thở riêng.','Hồng, cẩm tú cầu, hoa phụ','Bán chạy');
INSERT IGNORE INTO products (slug,name,category,occasion,price,old_price,image,description,flowers,badge) VALUES ('khu-vuon-nho','Khu vườn nhỏ','Bình hoa','Cảm ơn',690000,NULL,'/images/garden.jpg','Mang một góc vườn vào không gian sống. Hoa theo mùa kết hợp tự nhiên trong bình thủy tinh.','Hoa vườn theo mùa, lá xanh',NULL);
