INSERT IGNORE INTO products (slug,name,category,occasion,price,old_price,image,description,flowers,badge) VALUES ('trong-veo','Trong veo','Bình hoa','Cảm ơn',590000,NULL,'/images/white.jpg','Sắc trắng tinh khôi làm dịu một ngày bận rộn. Thiết kế thanh lịch phù hợp bàn làm việc và phòng khách.','Hoa trắng theo mùa, lá phụ',NULL);
INSERT IGNORE INTO products (slug,name,category,occasion,price,old_price,image,description,flowers,badge) VALUES ('ngay-chung-doi','Ngày chung đôi','Hoa cưới','Ngày cưới',1250000,NULL,'/images/peony.jpg','Bó hoa cầm tay với dáng tròn tự nhiên, gam màu thanh nhã dành cho ngày đặc biệt của hai người.','Hoa hồng vườn, hoa theo mùa','Đặt trước');
INSERT IGNORE INTO products (slug,name,category,occasion,price,old_price,image,description,flowers,badge) VALUES ('gui-binh-yen','Gửi bình yên','Giỏ hoa','Cảm ơn',650000,NULL,'/images/garden.jpg','Một giỏ hoa mộc mạc, bình dị và đầy sức sống. Gửi lời cảm ơn từ những điều nhỏ nhất.','Hoa cúc, hoa vườn, lá xanh',NULL);
